function openBlocked(x,y,zone){const z=openSpaces[zone];if(!z)return false;if(x<1||y<3||x>=z.width/40-1||y>=z.height/40-2)return true;if(z.rocket&&y>=6&&y<=7&&[[4,8],[10,14],[16,20]].some(([a,b])=>x>=a&&x<=b))return true;return zone==='forest'&&x>=26&&x<=28&&!(y>=14&&y<=16);}
