function normalizeOpenProgress(raw={}){return {cleared:[...new Set((Array.isArray(raw?.cleared)?raw.cleared:[]).filter(k=>typeof k==='string'&&/^\d+,\d+$/.test(k)&&(()=>{const [x,y]=k.split(',').map(Number);return !openBlocked(x,y,'diglands')})()))].slice(0,2400)};}
function clearOpenGround(progress,x,y){const cell=Math.floor(x/40)+','+Math.floor(y/40);if(!openBlocked(Math.floor(x/40),Math.floor(y/40),'diglands')&&!progress.cleared.includes(cell))progress.cleared.push(cell);}
