function defaultAquatic(){return {version:1,habitat:'lake',vehicle:'swim',observed:[],samples:[],completed:[],modules:[],pressure:0,depth:0,ballast:0,volcano:0,salinity:false,ping:0};}
function normalizeAquatic(raw={}){const s=defaultAquatic();if(!raw||typeof raw!=='object')return s;if(aquaticHabitats[raw.habitat])s.habitat=raw.habitat;if(raw.vehicle==='sub')s.vehicle='sub';for(const [key,valid]of [['observed',aquaticLife.map(a=>a.id)],['samples',aquaticSamples.map(a=>a.id)],['completed',['pressure','depth','buoyancy','volcano','sonar','habitat','salinity']],['modules',['beam-kit','foundation-kit','tower-kit','pipe-kit','valve-kit','power-kit','printed-kit','lift-kit','robot-kit']]])s[key]=[...new Set((Array.isArray(raw[key])?raw[key]:[]).filter(v=>valid.includes(v)))];for(const [key,max]of [['pressure',5],['depth',4],['ballast',2],['volcano',3]])if(Number.isInteger(raw[key])&&raw[key]>=0&&raw[key]<=max)s[key]=raw[key];s.salinity=raw.salinity===true;s.ping=raw.ping===1?1:0;return s;}
function aquaticVisible(s,o){return !o.habitat||o.habitat===s.habitat;}
function aquaticBlocked(x,y){return x<1||x>23||y<3||y>12;}
function aquaticAction(input,a,kits=[]){const s=normalizeAquatic(input);let route=a.route||'center',travel=null,reset=false,message='';const done=id=>{if(!s.completed.includes(id))s.completed.push(id)};
 if(a.type==='habitat'&&aquaticHabitats[a.value]){s.habitat=a.value;reset=true;message=aquaticHabitats[a.value].note;route='center';}
 if(a.type==='explore'&&aquaticHabitats[a.value]){s.habitat=a.value;s.vehicle='swim';reset=true;route='trail';message='Ready to swim in '+aquaticHabitats[a.value].name+'.';}
 if(a.type==='vehicle'&&['swim','sub'].includes(a.value)){s.vehicle=a.value;route='dock';message=a.value==='sub'?'Submersible ready. Tap a destination to travel.':'Ready to swim. Tap a destination.';}
 if(a.type==='observe'&&aquaticLife.some(l=>l.id===a.value)){if(!s.observed.includes(a.value))s.observed.push(a.value);route='life:'+a.value;message='Observation saved. The animal stays free.';}
 if(a.type==='sample'&&aquaticSamples.some(l=>l.id===a.value)){if(!s.samples.includes(a.value))s.samples.push(a.value);route='collection';message='Sample record saved. I can explore again.';}
 if(a.type==='step'){const limits={pressure:5,depth:4,ballast:2,volcano:3};if(a.key in limits){s[a.key]=(s[a.key]+1)%(limits[a.key]+1);if(s[a.key]===limits[a.key])done(a.key==='ballast'?'buoyancy':a.key)}}
 if(a.type==='salinity'){s.salinity=!s.salinity;done('salinity');}
 if(a.type==='ping'){s.ping=1-s.ping;done('sonar');if(!s.samples.includes('sonar'))s.samples.push('sonar');}
 if(a.type==='fit'&&kits.includes(a.value)){if(!s.modules.includes(a.value))s.modules.push(a.value);done('habitat');route='habitat';message='Reusable habitat model fitted.';}
 if(a.type==='travel')travel=a.value;
 return {aquatic:s,route,travel,reset,message,resume:a.type==='explore'&&!!aquaticHabitats[a.value]};
}
