function defaultConstruction(){return {version:1,active:null,selected:'beam',rotation:0,boards:{},completed:[],kits:[],printer:0,crane:0,robot:0,power:false,hints:false,history:[],elevator:0,orbit:false,modules:[]};}
function normalizeConstruction(raw={}){const s=defaultConstruction();if(!raw||typeof raw!=='object')return s;for(const id of Object.keys(constructionProjects)){const a=raw.boards?.[id];if(Array.isArray(a))s.boards[id]=Array.from({length:60},(_,i)=>{const p=a[i];return p&&constructionParts.some(k=>k[0]===p.part)?{part:p.part,rotation:Number.isInteger(p.rotation)?((p.rotation%4)+4)%4:0}:null})}s.completed=[...new Set((Array.isArray(raw.completed)?raw.completed:[]).filter(k=>constructionProjects[k]))];s.kits=[...new Set((Array.isArray(raw.kits)?raw.kits:[]).filter(k=>constructionKits.includes(k)))];for(const k of ['printer','crane','robot'])if(Number.isInteger(raw[k])&&raw[k]>=0&&raw[k]<=3)s[k]=raw[k];s.power=raw.power===true;s.hints=raw.hints===true;s.elevator=Number.isInteger(raw.elevator)&&raw.elevator>=0&&raw.elevator<=3?raw.elevator:0;s.modules=[...new Set((Array.isArray(raw.modules)?raw.modules:[]).filter(k=>constructionKits.includes(k)))];return s;}
function buildFixed(project,x,y){return project==='bridge'&&y>=3&&(x<=1||x>=10)||project==='gap'&&y>=3&&(x<4||x>7)||project==='pipes'&&(x===0||x===11)&&y===2||project==='power'&&(x===0&&(y===1||y===3)||x===11&&y>=1&&y<=3)||project==='water'&&y===2&&x!==6;}
function openBuild(s,id){if(!constructionProjects[id])return false;s.active=id;s.selected=constructionProjects[id].part;s.rotation=0;s.orbit=false;s.boards[id]??=Array(60).fill(null);s.history=[];return true;}
function placeBuild(s,x,y){if(!s.active||x<0||x>=12||y<0||y>=5||buildFixed(s.active,x,y))return false;const a=s.boards[s.active],i=y*12+x;s.history.push(a.map(c=>c?{...c}:null));if(s.history.length>12)s.history.shift();const old=a[i];const rotate=['straight','elbow','valve'].includes(s.selected);a[i]=old?.part===s.selected?(rotate?{part:s.selected,rotation:(old.rotation+1)%4}:null):{part:s.selected,rotation:rotate?s.rotation:0};return true;}
function buildPipePorts(cell){if(!cell)return [];const base=cell.part==='straight'?[1,3]:cell.part==='elbow'?[0,1]:cell.part==='valve'&&cell.rotation%2===0?[1,3]:[];return base.map(v=>(v+cell.rotation)%4);}
