 if(id==='free'){if(!s.completed.includes('free'))s.completed.push('free');return {ok:true,message:'My free build is saved. I can change it, test ideas and keep inventing. There is no required answer.'};}
 if(id==='pipes'){const q=[[1,2]],seen=new Set();while(q.length){const [x,y]=q.shift(),key=x+','+y;if(x<1||x>10||y<0||y>4||seen.has(key))continue;seen.add(key);const c=a[y*12+x];if(x===10&&y===2&&buildPipePorts(c).includes(1)){ok=buildPipePorts(a[25]).includes(3);break}for(const d of buildPipePorts(c)){const [dx,dy]=[[0,-1],[1,0],[0,1],[-1,0]][d],n=[x+dx,y+dy];if(buildPipePorts(a[n[1]*12+n[0]]).includes((d+2)%4))q.push(n)}}}
