function buildAction(s,action){if(action==='undo'&&s.history.length)s.boards[s.active]=s.history.pop();if(action==='reset'){s.history.push(s.boards[s.active].map(c=>c?{...c}:null));if(s.history.length>12)s.history.shift();s.boards[s.active]=Array(60).fill(null);}if(action==='hint')s.hints=!s.hints;if(action==='robot'){if(s.active==='power')s.power=true;s.history.push(s.boards[s.active].map(c=>c?{...c}:null));if(s.history.length>12)s.history.shift();if(s.active!=='free')s.boards[s.active]=Array(60).fill(null);for(const [x,y,part,rotation]of constructionProjects[s.active].solution)if(s.active!=='free'||!s.boards.free[y*12+x])s.boards[s.active][y*12+x]={part,rotation};s.hints=true;}if(action==='power')s.power=!s.power;}
function machineStep(s,id){if(!['printer','crane','robot'].includes(id))return;s[id]=(s[id]+1)%4;if(s[id]===3){const kit={printer:'printed-kit',crane:'lift-kit',robot:'robot-kit'}[id];if(!s.kits.includes(kit))s.kits.push(kit)}}
function constructionView(s,page='projects'){const go=(label,value)=>({label,type:'page',value}),act=(label,type,value)=>({label,type,value});if(page==='professor')return {title:professorElon.name,text:professorElon.intro+' '+professorElon.handoff,art:'professor',actions:[go('🏗 Choose an engineering plan','projects'),go('▣ Invent a free build','free'),go('🚀 Build a model rocket','rocket'),go('🤖 PIP, the next part','pip-help')]};if(page==='pip-help'){const project=constructionProjects[s.active];return {title:'PIP / Our next engineering step',text:project?'PIP: “'+project.text+' We can try one part, or I can show the plan.”':'PIP: “Choose one engineering plan or a model rocket. You choose the parts; I can help fit them. There is no hurry.”',art:'robot-0',actions:[...(project?[act('← Keep building','resume'),act('🤖 PIP show the plan','demonstrate')]:[go('🏗 Choose a plan','projects'),go('🚀 Choose a rocket','rocket')]),go('🧑‍🔬 Professor Elon','professor'),act('🏠 Return home','home')]};}if(page==='free')return {title:'My free build',text:'Build with blocks, beams and platforms. No required answer. Reset and robot demonstrations can be undone.',art:'yard',actions:[act('Open free build','build','free'),go('My construction parts','parts'),go('Construction challenges','projects')]};if(page==='projects')return {title:'Construction challenges',text:'Tap a plan. Fit prefabs with one tap. Test, change and repeat. PIP can show or demonstrate the plan.',art:'yard',actions:Object.entries(constructionProjects).filter(([id])=>id!=='free').map(([id,p])=>act((s.completed.includes(id)?'✓ ':'')+p.name,'build',id))};
 if(['printer','crane','robot'].includes(page)){const data={printer:['3D printer',['Plan a part before printing. A printer follows a digital design.','Use prepared feedstock. Raw rocks are not ready-to-print plastic or metal.','The printer adds material in layers. Different printers use different processes.','Inspect the printed part. Strength depends on material, design and how it was made.']],crane:['Crane bay',['A crane moves a load to a planned place. People choose and check the job.','The crane picks up the load with suitable lifting equipment in our model.','The load moves while the model keeps a stable base. This is not real operating guidance.','Place and inspect. Our reusable lifting kit is saved.']],robot:['Builder robots',['People plan the task. Robots do not replace human judgment.','Sensors can help a robot find a part or check a position.','A robot can repeat a placement task. People check the equipment and result.','Our builder helper has finished its demonstration. Robot kit saved.']]};return {title:data[page][0],text:data[page][1][s[page]],art:page+'-'+s[page],actions:[act('▶ Next step','machine',page),go('▣ Build something','projects'),go('📦 My construction parts','parts')]};}
 if(page==='parts')return {title:'My construction parts',text:s.kits.length?'Reusable parts for farm, habitats and future worlds. They are saved keepsakes, not points.':'Try a machine or construction challenge to keep a reusable part.',art:'parts',actions:[...s.kits.slice(0,3).map(k=>act('Fit '+k.replaceAll('-',' '),'fit',k)),...(s.kits.length>3?[act('More parts →','parts',3)]:[]),go('Space elevator project','elevator'),go('Construction plans','projects')]};
 if(page.startsWith('parts:')){const n=Number(page.split(':')[1])||0;return {title:'My construction parts',text:'Fit a saved model part at the farm. Parts stay available for future plans.',art:'parts',actions:[...s.kits.slice(n,n+3).map(k=>act('Fit '+k.replaceAll('-',' '),'fit',k)),...(n>0?[go('← Previous','parts:'+Math.max(0,n-3))]:[]),...(s.kits.length>n+3?[go('Next →','parts:'+(n+3))]:[]),go('Construction plans','projects')]};}
 if(page==='elevator'){const ready=constructionKits.every(k=>s.kits.includes(k));return {title:'Home Base space elevator',text:s.elevator===3?'Our training elevator model is assembled. Ride to an animated orbital preview. Real space elevators and generated colony systems remain future work.':ready?'Our nine training kits can assemble a foundation, tower/tether and orbital dock MODEL. Real Earth space elevators do not currently exist.':'Our long-term project needs structure, foundation, pipes, valve, power, printing, lifting and robotics kits. Keep practicing: no parts are consumed.',art:'elevator',actions:[...(ready&&s.elevator<3?[act(['Fit training foundation','Fit tower / tether model','Fit orbital dock model'][s.elevator],'foundation')]:[]),...(s.elevator===3?[act('Ride model elevator','orbit')]:[]),go('My construction parts','parts'),go('Construction plans','projects')]};}

 if(page==='pipes'||page==='power')return {title:page==='pipes'?'Pipe connections':'Model electrical power',text:page==='pipes'?'Openings must meet so water has a connected route. A valve controls flow.':'A circuit needs a complete path from a source through a load and back. This low-detail model is not wiring guidance.',art:page,actions:[act(page==='pipes'?'Connect pipes':'Connect power','build',page),...(page==='pipes'?[act('Try a valve','build','water')]:[]),go('Construction plans','projects')]};
 return constructionView(s,'projects');}
