function constructionPalette(id){return id==='pipes'?['straight','elbow']:id==='water'?['valve']:id==='power'?['wire']:id==='tower'?['block','platform','beam']:id==='gap'?['block','beam']:['beam','block','platform'];}
function constructionDispatch(s,a){if(a.type==='machine'){machineStep(s,a.value);return a.value}if(a.type==='parts')return 'parts:'+a.value;if(a.type==='foundation'&&constructionKits.every(k=>s.kits.includes(k))){s.elevator=Math.min(3,s.elevator+1);return 'elevator'}if(a.type==='orbit'&&s.elevator===3){s.orbit=true;s.phase=0;return null}return a.value||'projects';}

function constructionPower(s){const a=s.boards.power||[];return s.power&&[1,3].every(y=>Array.from({length:10},(_,i)=>a[y*12+i+1]?.part==='wire'&&a[y*12+i+1].rotation%2===0).every(Boolean));}

