function digCell(x,y){return [Math.max(1,Math.min(23,Math.floor(x/40))),Math.max(4,Math.min(12,Math.floor(y/40)))];}
function digBlocked(x,y,level=0){return x<1||x>23||y<4||y>12||(level===1&&y===12&&x>=17&&x<=22);}
function initialDigOpen(x,y,level){return y===4||(level===1&&x>=3&&x<=14&&y>=8);}
function defaultDig(){return {level:0,tool:'drill',hints:false,cleared:[[],[]],path:[],target:null,progress:0,ping:0,water:0,formation:0};}
function normalizeDig(raw={}){const s=defaultDig();if(!raw||typeof raw!=='object')return s;for(const k of ['ping','water','formation'])if(raw[k]===1)s[k]=1;if(raw.level===1)s.level=1;if(['drill','scoop','arms'].includes(raw.tool))s.tool=raw.tool;s.hints=raw.hints===true;for(let l=0;l<2;l++)s.cleared[l]=[...new Set((Array.isArray(raw.cleared?.[l])?raw.cleared[l]:[]).filter(k=>typeof k==='string'&&/^\d+,\d+$/.test(k)&&!digBlocked(...k.split(',').map(Number),l)))];return s;}
function digSolid(s,x,y){return !initialDigOpen(x,y,s.level)&&!s.cleared[s.level].includes(x+','+y);}
function digHard(x,y){return x>=17&&y>=7;}
function digRoute(from,to,level=0){const a=digCell(...from),b=digCell(...to),key=p=>p.join(',');if(digBlocked(...b,level))return [];const q=[a],parent=new Map([[key(a),null]]);for(let i=0;i<q.length;i++){const p=q[i];if(key(p)===key(b)){const out=[];let n=p;while(parent.get(key(n))!==null){out.push(n);n=parent.get(key(n));}return out.reverse()}for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const n=[p[0]+dx,p[1]+dy];if(digBlocked(...n,level)||parent.has(key(n)))continue;parent.set(key(n),p);q.push(n)}}return [];}
function digDuration(s,x,y,crew){if(!digSolid(s,x,y))return .08;let n=digHard(x,y)?.8:.22;if(s.tool==='scoop'&&y<=6)n*=.65;if(s.tool==='drill'&&y>6)n*=.75;if(s.tool==='arms'&&digHard(x,y))n*=.7;return crew===3?n*.42:n;}
function beginDig(s,from,to,target=null){s.path=digRoute(from,to,s.level);s.progress=0;s.target=target;return s.path.length>0||digCell(...from).join()===digCell(...to).join();}
function tickDig(s,position,dt,crew){let arrived=null,found=null,changed=false;s.progress+=Math.min(dt,.1);if(s.path.length){const [x,y]=s.path[0];if(s.progress>=digDuration(s,x,y,crew)){s.progress=0;if(digSolid(s,x,y)){s.cleared[s.level].push(x+','+y);if(y>4&&digSolid(s,x,y-1))s.cleared[s.level].push(x+','+(y-1));changed=true}position=[x*40+20,y*40+20];s.path.shift();const f=digObjects.find(o=>o.level===s.level&&o.find&&digCell(o.x,o.y).join()===[x,y].join());if(f)found=f.find;}}if(!s.path.length&&s.target){arrived=s.target;s.target=null}return {position,arrived,found,changed};}
function digVisible(s,o){if(o.level!==s.level)return false;if(!o.find||s.hints)return true;const [x,y]=digCell(o.x,o.y);return [[x,y],[x-1,y],[x+1,y],[x,y-1],[x,y+1]].some(([a,b])=>!digSolid(s,a,b));}
function digView(s,page,crew=0){const action=(label,type,value)=>({label,type,value});if(page==='tools')return {title:'Digging tools',text:crew===3?'Aiden has drills, scoops and power arms. His heavy engineering rig breaks hard rock directly.':'Choose a tool. PIP automatically helps with the hardest rock. Every astronaut can explore.',art:'tools',actions:[action('⚙ Drill','tool','drill'),action('▱ Scoop','tool','scoop'),action('🦾 Power arms','tool','arms'),action('✨ Show finds','hints',true),action('↺ Reset tunnels','reset')]};const l=digLessons[page]||digLessons.layers;return {...l,art:page,actions:page==='echo'?[action('◉ Send ping','ping')]:page==='groundwater'?[action('🌧️ Rain / recharge','water')]:page==='formations'?[action('Ceiling / floor','formation')]:[]};}
