function defaultFarm(){return {garden:emptyGarden(),constructionModules:[],upgrades:{},seeds:[],experiments:[],growth:0,shade:false,vent:false,pump:false,pollen:0,water:0,recycle:0,zoom:0,robot:0,sun:false,wind:false,flow:false}}
function normalizeFarm(input={}){const f=defaultFarm();if(!input||typeof input!=='object')return f;f.constructionModules=[...new Set((Array.isArray(input.constructionModules)?input.constructionModules:[]).filter(k=>['beam-kit','foundation-kit','tower-kit','pipe-kit','valve-kit','power-kit','printed-kit','lift-kit','robot-kit'].includes(k)))];for(const k of ['bridge','water','habitat'])if(['quartz','iron','amethyst','calcite','granite','basalt'].includes(input.upgrades?.[k]))f.upgrades[k]=input.upgrades[k];f.seeds=[...new Set((Array.isArray(input.seeds)?input.seeds:[]).filter(id=>farmPlants.some(p=>p.id===id)))];f.garden=normalizeGarden(input.garden,f.seeds);f.experiments=[...new Set((Array.isArray(input.experiments)?input.experiments:[]).filter(id=>farmExperiments[id]))];for(const k of ['shade','vent','pump','sun','wind','flow'])f[k]=input[k]===true;for(const [k,max]of [['growth',5],['pollen',3],['water',4],['recycle',3],['zoom',3],['robot',3]])if(Number.isInteger(input[k])&&input[k]>=0&&input[k]<=max)f[k]=input[k];return f}
function farmDestination(site){return ({garden:'farm-garden',orchard:'farm-orchard',hydro:'farm-hydro',biodome:'farm-biodome',vertical:'farm-vertical'})[site]||'farm-computer'}
function farmAction(input,action){const f=normalizeFarm(input);let route=action.route||'home',travel=null,message='';const done=id=>{if(!f.experiments.includes(id))f.experiments.push(id)};
 if(action.type==='collect'){const p=farmPlants.find(p=>p.id===action.id);if(p){if(!f.seeds.includes(p.id)){f.seeds.push(p.id);message=p.name+' sample seed saved.'}else message=p.name+' is already safe in my seed bank.';gardenCollect(f.garden,p.id,action.origin||'tray');route='plant:'+p.id;}}
 if(action.type==='garden'){if(action.command==='starter'){if(!f.seeds.includes('bean'))f.seeds.push('bean');gardenCollect(f.garden,'bean','starter');message='Bean seed saved. Choose a bed to plant it.';route=action.route||'choose-bed:bean';}else{const result=gardenCommand(f.garden,f.seeds,action);f.garden=result.garden;message=result.message;route='bed:'+(Number.isInteger(action.bed)&&action.bed>=0&&action.bed<3?action.bed:0);}}
 if(action.type==='travel'){const p=farmPlants.find(p=>p.id===action.id);travel=p?farmDestination(p.site):action.target;}
 if(action.type==='toggle'&&['shade','vent','pump','sun','wind','flow'].includes(action.key)){f[action.key]=!f[action.key];done(action.key==='pump'?'hydro':['shade','vent'].includes(action.key)?'greenhouse':'energy');}
 if(action.type==='step'){const limits={growth:5,pollen:3,water:4,recycle:3,zoom:3,robot:3};if(action.key in limits){f[action.key]=(f[action.key]+1)%(limits[action.key]+1);if(f[action.key]===limits[action.key])done(({pollen:'pollination',zoom:'leaf'})[action.key]||action.key);}}
 return {farm:f,route,travel,message};
}
