function gardenView(f,route){const [page,arg='',pageString='0']=route.split(':'),bed=Number(arg),n=Math.max(0,parseInt(pageString)||0),g=f.garden;const go=(label,to)=>({label,action:{type:'page',route:to}}),cmd=(label,command,bed,seed)=>({label,action:{type:'garden',command,bed,seed}}),back=go('← My garden','garden');const view=(title,body,visual,actions)=>({title,body,visual,actions});
 if(page==='garden')return view('My garden','Choose a bed. Plant a saved seed, water it, then leave the farm and come back. Each watered visit grows one stage. Plants wait safely for you.','🫘 → 💧 → 🌱',[
 ...g.plots.map((p,i)=>go((p.seed?farmPlants.find(s=>s.id===p.seed).icon:'＋')+' Bed '+(i+1)+(p.seed?' / '+farmPlants.find(s=>s.id===p.seed).name:''),'bed:'+i)),go('🫘 My seed bank','bank'),go('🔬 Growth lab','growth')]);
 if(page==='bed'){if(!Number.isInteger(bed)||bed<0||bed>2)return gardenView(f,'garden');const p=g.plots[bed],plant=farmPlants.find(s=>s.id===p.seed);if(!plant)return view('Bed '+(bed+1)+' / Empty','Choose a seed from your seed bank. Each collected kind is reusable in this game.','＋ → 🫘 → 🌱',[go('🫘 Choose a seed','sow:'+bed+':0'),...(!f.seeds.length?[cmd('🫘 Get a bean seed','starter',bed)]:[]),back]);const mature=p.stage===3;return view('Bed '+(bed+1)+' / '+plant.name,gardenStages[p.stage]+'. '+(mature?(p.harvested?'Harvest saved. Keep this plant or plant again.':'Your model plant is grown! Collect it, or keep it here.'):(p.watered?'Watered. Leave the farm, then return for one new stage.':'Tap Water. Then leave the farm and come back.'))+' This model skips real growing time; real plants need suitable light, air, nutrients, water and temperature.',plant.icon,[...(mature?[...(!p.harvested?[cmd('🧺 Collect harvest','harvest',bed)]:[]),go('🌱 Plant again','sow:'+bed+':0')]:[cmd(p.watered?'✓ Watered / remind me':'💧 Water plant','water',bed),{label:'🌍 Go exploring',action:{type:'travel',target:'grounds-home'}}]),go('🔎 About my plant','plant:'+plant.id),back]);}
 if(page==='sow'){if(!Number.isInteger(bed)||bed<0||bed>2)return gardenView(f,'garden');const p=g.plots[bed];if(p.seed&&p.stage<3)return view('This bed is growing','Your plant is safe. Water it and return, or choose another bed.','🌱',[back]);const rows=f.seeds.slice(n*2,n*2+2).map(id=>{const s=farmPlants.find(p=>p.id===id);return cmd(s.icon+' Plant '+s.name,'plant',bed,id)});if(n>0)rows.push(go('← Previous seeds','sow:'+bed+':'+(n-1)));if(f.seeds.length>(n+1)*2)rows.push(go('More seeds →','sow:'+bed+':'+(n+1)));if(!f.seeds.length)rows.push(cmd('🫘 Get a bean seed','starter',bed));rows.push(back);return view('Choose a seed / Bed '+(bed+1),f.seeds.length?'These are your collected seeds. Tap one to plant it.':'Your bank is ready. Get a starter bean, or find plants while exploring.','🫘 → 🌱',rows);}
 if(page==='choose-bed'){const plant=farmPlants.find(p=>p.id===arg);if(!plant||!f.seeds.includes(arg))return view('Find a seed first','Collect a seed before planting it.','🫘',[go('🫘 My seed bank','bank'),back]);const available=g.plots.flatMap((p,i)=>!p.seed||p.stage===3?[cmd((p.seed?'↻ Replant':'🌱 Plant in')+' Bed '+(i+1),'plant',i,arg)]:[]);return view('Plant '+plant.name,available.length?'Choose an empty bed, or replant a grown one. Your seed bank keeps this reusable sample.':'All three beds are growing. Water a plant and return to see it grow.',plant.icon,[...available,back]);}
 return null;
}

