// Repeatable illustrated tools, available to every crew member. These are teaching models.
const pipToolLessons={
 'life-lens':{title:'Life lens — Lucas',steps:[['Plant cell','This model shows a plant cell. A cell wall surrounds it. Cells are tiny units of living things.'],['Inside the cell','The nucleus contains most of this cell’s DNA. This picture is simplified; cell parts are not drawn to scale.'],['Chloroplasts','Chloroplasts use light energy in photosynthesis. Many green plant cells have them; animal cells do not.']]},
 'xeno-lab':{title:'Xeno lab — Lucas',steps:[['Look for conditions','Life as we know it needs liquid water, energy and suitable chemical ingredients. We can investigate those conditions on other worlds.'],['Evidence, not proof','An ocean or organic molecules can make a place interesting to study. Neither proves that organisms live there. No extraterrestrial life has been confirmed.'],['Imagine and compare','This imaginary organism is fiction. What might help it live in its imagined habitat? Real biology and invented alien life are different kinds of exploration.']]},
 'eco-probe':{title:'Eco probe — Sumati',steps:[['Plant and pollinator','Some animals move pollen between flowers while visiting them. Many plants depend on animal pollinators, but others use wind or other methods.'],['Water, soil and life','Plants take up water through roots. Water, soil, air and organisms interact. A change in one part of a habitat can affect other parts.'],['Care for a habitat','Habitat restoration can help living things by improving their surroundings. It takes planning, time and observation. Our model shows connections, not an instant fix.']]},
 'pattern-projector':{title:'Pattern projector — Lilja',steps:[['What repeats?','Circle, square, circle, square. The repeating unit is circle then square. Tap again to explore another mathematical idea.'],['Count in groups','Two dots and two more dots make four dots: 2 + 2 = 4. We can count each dot or combine groups.'],['Mirror symmetry','The shapes on each side match across the mirror line. A reflection changes left and right while keeping shape and size.']]}
};
function pipToolView(tool,step=0){const id=Object.hasOwn(pipToolLessons,tool)?tool:'life-lens',lesson=pipToolLessons[id],index=Number.isInteger(step)?((step%lesson.steps.length)+lesson.steps.length)%lesson.steps.length:0;return {tool:id,step:index,title:lesson.title,heading:lesson.steps[index][0],text:lesson.steps[index][1],art:id+'-'+index};}
