 if(id==='xeno-lab'){shapes='<circle cx="80" cy="90" r="52" fill="#d5e9e6"/><path d="M40 93q40-45 80 0v20q-40 40-80 0z" fill="#60b3cf"/><circle cx="230" cy="90" r="50" fill="#e4d7bd"/>';shapes+=index===0?'<path d="M130 90h45" stroke="#d7a336" stroke-width="8"/><path d="M165 78l14 12-14 12" fill="none"/>':index===1?'<text x="230" y="110" text-anchor="middle" font-size="60" fill="#8653b6">?</text>':'<ellipse cx="230" cy="98" rx="22" ry="30" fill="#8653b6"/><circle cx="222" cy="87" r="5" fill="#fffbed"/><circle cx="238" cy="87" r="5" fill="#fffbed"/><text x="230" y="165" text-anchor="middle" font-size="16" fill="#17384a">IMAGINARY</text>';}
 if(id==='eco-probe'){shapes='<path d="M95 145V70m0 35q-35 0-35-30 30 0 35 30m0-15q30 0 30-28-30 0-30 28" fill="#8aba7d" stroke-width="6"/><circle cx="95" cy="50" r="22" fill="#e9b4cb"/><circle cx="95" cy="50" r="8" fill="#f4d37e"/><path d="M145 95h45m-10-10 10 10-10 10" fill="none" stroke-width="6"/>';if(index===0)shapes+='<ellipse cx="230" cy="88" rx="30" ry="18" fill="#f4d37e"/><ellipse cx="220" cy="63" rx="15" ry="17" fill="#d5e9e6"/><ellipse cx="244" cy="63" rx="15" ry="17" fill="#d5e9e6"/><path d="M225 73v29m14-27v25"/>';else if(index===1)shapes+='<path d="M235 40q-60 70 0 82 60-12 0-82z" fill="#60b3cf"/><path d="M55 150h220" stroke="#aa8562" stroke-width="12"/>';else shapes+='<path d="M225 140V76m0 35-20-18m20 2 20-17" stroke="#39864a" stroke-width="8"/><path d="M195 150h65" stroke="#aa8562" stroke-width="12"/><circle cx="270" cy="42" r="17" fill="#f4d37e"/>';}
