const allSuitPowers=Object.values(suitPowers).flat();
function normalizeSuit(raw={}){return {overlay:allSuitPowers.some(p=>p.id===raw?.overlay)?raw.overlay:null,records:[...new Set((Array.isArray(raw?.records)?raw.records:[]).filter(id=>allSuitPowers.some(p=>p.id===id)))]};}
