function suitSubject(power,o){if(!o||['portal','home','diglevel','digtools','crew','workshop'].includes(o.kind))return false;if(power.kind==='all')return true;const living=o.life||o.id==='plant'||/^farm-(garden|orchard|leaf|biodome|hydro|vertical|robot|water)/.test(o.id)||/^cave-(life|pigment|echo)/.test(o.id);return !!(living||power.kind==='environment'&&/water|habitat|cleanup|plant|soil/.test(o.id));}
