function suitOverlayPoints(power,zone,habitat='lake',level=0){return objects.filter(o=>o.zone===zone&&(zone!=='dig'||o.level===level)&&(!o.habitat||o.habitat===habitat)&&suitSubject(power,o)).slice(0,12);}
function suitOverlay(power,zone,habitat='lake',level=0,camera=[0,0]){const points=suitOverlayPoints(power,zone,habitat,level).map(o=>({...o,x:o.x-camera[0],y:o.y-camera[1]}));let shapes='';if(power.id==='measure-map'){for(let x=20;x<1000;x+=40)shapes+=`<path d="M${x} 100v420"/>`;for(let y=100;y<520;y+=40)shapes+=`<path d="M20 ${y}h960"/>`;}for(const o of points)shapes+=`<circle data-suit-target="${o.id}" cx="${o.x}" cy="${o.y}" r="48" stroke-width="5"/>`;if(['connection-vision','restoration-planner','geometry-builder'].includes(power.id))for(let i=1;i<points.length;i++)shapes+=`<path d="M${points[i-1].x} ${points[i-1].y}L${points[i].x} ${points[i].y}" stroke-width="4" stroke-dasharray="10 8"/>`;return '<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="600"><g stroke="#ac72df" opacity=".8" fill="none" stroke-width="1">'+shapes+'</g></svg>';}

