function activeObjects(){if(state.expeditions.active)return [];return objects.filter(o=>!state.construction.active&&!state.construction.orbit&&o.zone===state.zone&&(state.zone!=='aquatic'||aquaticVisible(state.aquatic,o))&&(state.zone!=='dig'||digVisible(state.excavation,o)))}
function changeZone(id){state.expeditions.active=null;if(!chapterCanVisit(id,state.firstVisit.mode,state.chapter,chapterDug())){showChapter();return false;}let gardenGrew=false;if(id==='farm'&&state.zone!=='farm'){const before=state.farm.garden.plots.map(p=>p.stage);state.farm=returnToFarm(state.farm);gardenGrew=before.some((stage,i)=>state.farm.garden.plots[i].stage>stage);persist();}state.zone=id;if(id==='aquatic')state.aquatic.habitat='lake';if(id==='dig'){state.excavation.level=0;state.excavation.path=[];state.excavation.target=null;}[state.x,state.y]=zones[id].spawn;state.path=[];state.pending=null;state.action=null;state.journey=null;state.ring=null;renderTargets();$('#zone-label').textContent=zones[id].name;canvas.setAttribute('aria-label',zones[id].name+'. Use the destination buttons to explore.');announce('Welcome to '+zones[id].name+'.'+(gardenGrew?' Your watered plants grew. Check your garden.':''));}
function select(o){if(state.expeditions.active)exitExpedition();if(!o)return;if(chapterWorlds[o.zone]&&o.zone!==state.zone){if(!chapterCanVisit(o.zone,state.firstVisit.mode,state.chapter,chapterDug())){showChapter();return;}changeZone(o.zone);}state.flightLanded=false;start();if(openSpaces[state.zone]&&o.id==='grounds-home'){changeZone('grounds');return;}if(state.paused){announce('Tap Resume to keep exploring.');return}if(state.construction.active||state.construction.orbit){state.construction.active=null;state.construction.orbit=false;renderTargets()}state.journey=null;if(o.zone!==state.zone){state.journey=o.id;o=objects.find(x=>x.id===zoneExit(state.zone,o.zone))}if(state.zone==='aquatic'&&o.habitat&&o.habitat!==state.aquatic.habitat){state.aquatic.habitat=o.habitat;state.x=180;state.y=460;renderTargets();}if(state.zone==='dig'){if(o.level!==state.excavation.level)setDigLevel(o.level);selectDigPoint(o.x,o.y,o.id);return}state.action=null;state.ring={x:o.x,y:o.y};state.pending=o;state.path=pathfind([state.x,state.y],[o.x-65,o.y+55],state.zone);announce('Going to '+o.name);if(!state.path.length){state.pending=null;const here=cellAt(state.x,state.y,state.zone),goal=cellAt(o.x-65,o.y+55,state.zone);if(here.join()===goal.join()&&!blocked(...goal,state.zone))interact(o);else{state.journey=null;announce('Choose a clear path to explore.');}}}
function renderTargets(){refreshElevatorObjective();refreshConstructionControls();$('#targets').replaceChildren();for(const o of activeObjects()){const plot=Number.isInteger(o.gardenBed)?state.farm.garden.plots[o.gardenBed]:null,plant=plot?.seed?farmPlants.find(p=>p.id===plot.seed):null;const b=button((plot?(plant?.icon||'＋'):o.icon)+' ',()=>select(o),$('#targets'));b.className='target'+(state.zone==='aquatic'&&(o.life||o.find)?' swim-target':'');b.dataset.id=o.id;b.dataset.badge=destinationBadge(objects,o.id);const camera=spaceCamera(state.zone,[state.x,state.y]),sx=o.x-camera[0],sy=o.y-camera[1];b.style.left=sx/10+'%';b.style.top=sy/6+'%';b.hidden=!!openSpaces[state.zone]&&(sx<45||sx>955||sy<130||sy>490);b.setAttribute('aria-label',plot?o.name+', '+(plant?plant.name+', '+gardenStages[plot.stage]:'Empty'):o.name);const label=document.createElement('small');label.textContent=o.name;b.append(label)}}
