function pipHelp(){if(state.expeditions.active){showExpedition('mission');return}if(state.zone==='rocketlab'){showRocketLab('help');return}if(['engineering','machineyard'].includes(state.zone)||['hq','flight'].includes(state.zone)&&['hq-elon','flight-elon'].includes(state.last)){showConstruction('pip-help');return}if(['coding','robotics'].includes(state.zone)){const last=objects.find(o=>o.id===state.last&&o.zone===state.zone&&o.kind==='tech');showTech('pip-help:'+(last?.page|| (state.zone==='coding'?'home':'build')));return}open('PIP • Your exploration helper');paragraph('🤖 → 👆 → ⛏️','illustration');button('✨ Show places',()=>{close();if(state.zone==='dig'){state.excavation.hints=true;renderTargets();}document.querySelectorAll('.target').forEach(b=>b.classList.add('hint'));announce('The bright pictures are places you can explore.');});button(state.zone==='aquatic'?'🏊 Show me a swim':'▶ Show me a dig',()=>{close();select(state.zone==='aquatic'?activeObjects().find(o=>o.life):objects.find(o=>o.id==='dig'))});button('↩ Previous activity',()=>{close();select(objects.find(o=>o.id===state.last)||objects.find(o=>o.id===zones[state.zone].home))});button('🔊 Repeat guidance',()=>{announce('Tap a picture. Your astronaut walks there and explores. Tap the pickaxe to dig.');speak('Tap a picture. Your astronaut walks there and explores. Tap the pickaxe to dig.')});button('🏠 Return home',()=>{close();select(objects.find(o=>o.id===zones[state.zone].home))});button('🛠 Build PIP',pipWorkshop);button('🔎 Analyze a discovery',pipDiscoveries)};
$('#pip').onclick=pipHelp;
function pipWorkshop(){open('PIP Workshop');panel.classList.add('pip-panel');mountPipWorkshop({root:content,config:state.pip,crewIndex:()=>activeCustomJacc(state.jaccBuilder)?jaccMatchIndex(activeCustomJacc(state.jaccBuilder),roster):activeAstronautIndex(),onChange:c=>{state.pip=c;persist();chime()},onDone:()=>{close();announce('PIP is ready to explore with '+activeAstronautName()+'.')},onTryTool:()=>pipToolLessons[state.pip.tool]?showPipTool(state.pip.tool):pipDiscoveries(),onAnalyze:pipDiscoveries,onHelp:pipHelp,onSpeak:readJournal});}
function showPipTool(tool,step=0){const v=pipToolView(tool,step);open(v.title);panel.classList.add('farm-panel');const info=document.createElement('div');info.className='farm-info';const art=document.createElement('div');art.className='farm-art';art.innerHTML=pipToolArt(v.art);const p=document.createElement('p');p.textContent=v.heading+'. '+v.text;info.append(art,p);content.append(info);button('▶ Next / repeat',()=>showPipTool(v.tool,v.step+1));button('🔊 Listen',()=>readJournal(v.heading+'. '+v.text));button('🛠 PIP Workshop',pipWorkshop);}
function pipDiscoveries(){open('Ask PIP');paragraph('Choose something I discovered.');const found=materials.filter(m=>state.discoveries.has(m.id));if(!found.length){paragraph('Dig to find our first sample.');button('⛏️ Go digging',()=>{close();select(objects.find(o=>o.id==='dig'))})}for(const m of found)button(m.icon+' '+m.name,()=>showPipAnalysis(m.id));button('← PIP Workshop',pipWorkshop);}
function showPipAnalysis(id){const a=pipAnalysis(id,state.pip.tool);if(!a)return;open('PIP investigates: '+a.title);panel.classList.add('pip-panel');paragraph(a.detail,'journal-intro');paragraph(a.formula,'diagram');const atoms=document.createElement('div');atoms.className='pip-atoms';atoms.setAttribute('aria-label','Illustrated formula pattern');for(const [symbol,name,count]of a.atoms){const group=document.createElement('div');group.className='pip-atom-group';for(let i=0;i<count;i++){const atom=document.createElement('span');atom.className='pip-atom';atom.textContent=symbol;atom.setAttribute('aria-hidden','true');group.append(atom)}const label=document.createElement('p');label.textContent=name+' × '+count;group.append(label);atoms.append(group)}content.append(atoms);paragraph(a.note,'journal-fact');paragraph('PIP uses our science guide. This is a simple model of the formula.');button('🔊 Listen',()=>readJournal(a.detail+' '+a.note));button('← My samples',pipDiscoveries);button('🛠 PIP Workshop',pipWorkshop);}
