function drawPipBuddy(x,y){const effective=state.expeditions.active==='ocean'?{...state.pip,travel:'swim'}:state.expeditions.active&&state.expeditions.worlds[state.expeditions.active].fly?{...state.pip,travel:'hover'}:state.zone==='aquatic'?{...state.pip,travel:'swim'}:state.zone==='flight'?{...state.pip,travel:'hover'}:state.pip;const key=JSON.stringify(effective);if(key!==pipImageKey){pipImageKey=key;pipImage=new Image();pipImage.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(pipSvg(effective));}if(pipImage?.complete&&pipImage.naturalWidth)ctx.drawImage(pipImage,x,y,70,70);}
$('#settings').onclick=()=>{open('Accessibility & sound');const volume=document.createElement('label');volume.textContent='🔊 Volume';const range=document.createElement('input');range.type='range';range.min=0;range.max=1;range.step=.1;range.value=state.settings.volume;range.setAttribute('aria-label','Sound volume');range.oninput=()=>{state.settings.volume=+range.value;persist()};volume.append(range);content.append(volume);for(const [key,label] of [['narration','🔊 Optional narration'],['reduced','🐢 Reduced animation'],['effects','✨ Visual effects'],['highContrast','◐ High contrast'],['colorBlind','🔢 Color-blind support']]){const l=document.createElement('label'),i=document.createElement('input');i.type='checkbox';i.checked=state.settings[key];i.onchange=()=>{state.settings[key]=i.checked;applyDisplay();persist()};l.append(i,document.createTextNode(label));content.append(l)}button('🧭 First Visit: GSEINHQ',firstVisitWelcome);button('♿ Adaptive access & My words',()=>adaptive.options());paragraph('Color-blind support adds numbered markers. Both display options can be used together.');paragraph('All activities wait for you. No dragging, fast tapping, scores, or penalties.');};
