function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(x,y,w,h)}
function drawPlan(plan){for(const p of plan){ctx.fillStyle=p.color;if(p.kind==='rect')ctx.fillRect(p.x,p.y,p.w,p.h);else if(p.kind==='ellipse'){ctx.beginPath();ctx.ellipse(p.x,p.y,p.w,p.h,0,0,Math.PI*2);ctx.fill()}else{ctx.font='bold '+p.size+'px system-ui';ctx.fillText(p.text,p.x,p.y)}}}
function drawHQ(){drawPlan(hqPlan);ctx.fillStyle='#eff8f5';ctx.font='bold 26px system-ui';ctx.fillText('GSEINHQ',40,60);}
function draw(t){if(state.expeditions.active){drawExpedition(t);return}expRoot.hidden=true;ctx=sceneCtx;ctx.clearRect(0,0,1000,600);if(state.construction.orbit)drawOrbit();else if(state.construction.active)drawConstruction(t);else if(openSpaces[state.zone])drawOpenSpace();else if(state.zone==='aquatic')drawAquatic();else if(state.zone==='dig')drawDig();else if(state.zone==='engineering')drawEngineering();else if(state.zone==='hq')drawHQ();else if(state.zone==='farm'){drawPlan(farmPlan);if(state.farm.upgrades.water||state.farm.constructionModules.some(k=>['pipe-kit','valve-kit'].includes(k)))rect(570,325,100,10,'#407c9b');if(state.farm.upgrades.habitat||state.farm.constructionModules.includes('printed-kit'))rect(355,200,110,10,'#407c9b');if(state.farm.upgrades.bridge||state.farm.constructionModules.some(k=>['beam-kit','foundation-kit','tower-kit'].includes(k)))rect(120,335,120,10,'#407c9b');drawGardenBeds();}else{rect(0,0,1000,600,'#b7d98d');rect(0,0,1000,90,'#a5deeb');ctx.fillStyle='#8ab96e';ctx.beginPath();ctx.ellipse(350,200,200,110,0,0,7);ctx.fill();ctx.strokeStyle='#e8cc94';ctx.lineWidth=70;ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(130,460);ctx.lineTo(290,460);ctx.lineTo(450,420);ctx.lineTo(730,420);ctx.lineTo(830,480);ctx.stroke();ctx.lineWidth=46;ctx.beginPath();ctx.moveTo(290,460);ctx.lineTo(220,245);ctx.lineTo(380,175);ctx.lineTo(500,110);ctx.lineTo(740,110);ctx.lineTo(815,180);ctx.lineTo(710,410);ctx.stroke();rect(520,160,160,160,'#4b9fb6');for(let y=185;y<310;y+=35)rect(540,y,110,5,'#95d5df');rect(735,135,180,100,'#8e6b55');rect(735,125,180,85,'#c6a17c');for(let i=0;i<5;i++)rect(735,220+i*16,150-i*22,13,'#ddbf91');rect(395,440,120,20,'#bd8b60');rect(395,460,120,15,'#986644');rect(395,475,120,12,'#71482f');ctx.fillStyle='#285344';ctx.font='bold 21px system-ui';ctx.fillText('GSEI • DISCOVERY TRAINING GROUNDS',35,46);ctx.font='16px system-ui';ctx.fillText('↖ Hill trail',280,105);ctx.fillText('Auto-climb ramp ↗',745,325);ctx.fillText('HOME HUB • HQ ←   •   PLANET FARM →',55,565);if(state.construction.elevator){rect(405,330,90,12,'#9ab6bc');if(state.construction.elevator>=2){rect(435,180,6,150,'#9ab6bc');rect(465,180,6,150,'#9ab6bc');}if(state.construction.elevator>=3){rect(400,175,100,14,'#edc46c');rect(449,95,3,80,'#9ab6bc');}}}
if(!state.construction.active&&!state.construction.orbit)drawSuitOverlay();
drawWildlife(false);drawMachinePlacements();drawRocketWorld();if(state.ring&&!openSpaces[state.zone]&&!state.construction.active&&!state.construction.orbit){ctx.strokeStyle=state.settings.effects?'#fff8b2':'#1a3547';ctx.lineWidth=5;ctx.beginPath();ctx.arc(state.ring.x,state.ring.y,25,0,7);ctx.stroke()}
actorCtx.clearRect(0,0,1000,600);if(state.construction.active||state.construction.orbit)return;ctx=actorCtx;const camera=spaceCamera(state.zone,[state.x,state.y]),x=state.x-camera[0],y=state.y-camera[1],bob=(state.path.length||(state.zone==='dig'&&state.excavation.path.length))&&!state.settings.reduced?Math.sin(t/90)*3:0;if(activeCustomJacc(state.jaccBuilder)){drawCustomAstronaut(x,y,bob);drawPipBuddy(x-85,y-80);ctx=sceneCtx;return;}if(state.zone==='flight'&&!state.flightLanded){ctx.fillStyle='#35d3c9';ctx.beginPath();ctx.ellipse(x,y+35,12,state.path.length?22:8,0,0,Math.PI*2);ctx.fill();}if(state.zone==='aquatic'&&state.aquatic.vehicle==='swim'){const frame=state.path.length&&!state.settings.reduced?Math.floor((state.swimPhase||0)*3)%2:0,img=swimImage('astronaut-'+characters.active[1]+'-'+frame,swimmerSvg(suitColors[characters.active[1]],frame));if(img.complete&&img.naturalWidth)ctx.drawImage(img,x-50,y-35,100,70);drawPipBuddy(x-85,y-80);ctx=sceneCtx;return;}if(state.zone==='aquatic'&&state.aquatic.vehicle==='sub'){ctx.fillStyle='#efd17c';ctx.beginPath();ctx.ellipse(x,y-8,61,35,0,0,Math.PI*2);ctx.fill();rect(x-76,y-20,20,24,'#e0bb64');ctx.fillStyle='#9bcbd7';ctx.beginPath();ctx.ellipse(x,y-10,33,29,0,0,Math.PI*2);ctx.fill();}ctx.fillStyle='#0003';ctx.beginPath();ctx.ellipse(x,y+20,20,7,0,0,7);ctx.fill();rect(x-16,y-15+bob,32,34,suitColors[characters.active[1]]);rect(x-12,y+16+bob,9,12,'#23384f');rect(x+4,y+16+bob,9,12,'#23384f');rect(x-19,y-42+bob,38,29,'#f5f4e4');rect(x-13,y-35+bob,26,15,'#28495e');rect(x-25,y-10+bob,8,22,'#e3e5cf');rect(x+17,y-10+bob,8,22,'#e3e5cf');if(['dig','diglands'].includes(state.zone)&&activeAstronautIndex()===3){rect(x+16,y-15,22,12,'#edc74d');rect(x+36,y-13,12,8,'#a0bdc5');}if(state.action==='dig'){ctx.font='30px system-ui';ctx.fillText('⛏️',x+18,y)}drawPipBuddy(x-85,y-80);if(state.zone==='dig'&&state.excavation.path.length){rect(x-38,y-42,22,8,'#9db5bf');}ctx=sceneCtx;}
let prev=performance.now();function loop(t){const dt=Math.min((t-prev)/1000,.05);prev=t;state.wildlifeTime=wildlifeClock(state.wildlifeTime||0,dt,{started:state.started,paused:state.paused,overlay:panel.open,reduced:state.settings.reduced,effects:state.settings.effects});if(state.expeditions.active){if(state.started&&!state.paused&&!panel.open)tickExpedition(dt);draw(state.paused?0:t);requestAnimationFrame(loop);return;}if(state.started&&!state.paused&&!panel.open){if(state.zone==='aquatic'&&!state.settings.reduced)state.swimPhase=(state.swimPhase||0)+dt;if(state.construction.orbit&&!state.settings.reduced)state.construction.phase=(state.construction.phase||0)+dt*.35;if(state.construction.active||state.construction.orbit){}else if(state.zone==='dig')updateDig(dt);else if(state.path.length){if(chapterWorlds[state.zone]){const count=state.chapter.cleared[state.zone].length;clearChapterGround(state.chapter,state.zone,...state.path[0]);if(count!==state.chapter.cleared[state.zone].length)persist();}if(state.zone==='diglands'){const p=state.path[0],key=Math.floor(p[0]/40)+','+Math.floor(p[1]/40);if(!state.openWorld.cleared.includes(key)){clearOpenGround(state.openWorld,...p);persist();}}const p=state.path[0],dx=p[0]-state.x,dy=p[1]-state.y,d=Math.hypot(dx,dy),step=(state.zone==='flight'?240:state.zone==='diglands'&&activeAstronautIndex()===3?240:state.zone==='aquatic'&&state.aquatic.vehicle==='sub'?190:150)*dt;if(d<=step){[state.x,state.y]=p;state.path.shift();if(!state.path.length&&state.pending){const o=state.pending;state.pending=null;interact(o)}}else{state.x+=dx/d*step;state.y+=dy/d*step}}if(!state.construction.active&&!state.construction.orbit&&state.action){state.timer-=dt;if(state.timer<=0){state.action=null;discover(materials[state.dug++%materials.length])}}}updateMachineDemo(dt);draw(state.paused?0:t);requestAnimationFrame(loop)}requestAnimationFrame(loop);


function adaptiveHelper(mode){if(state.expeditions.active){showExpedition(mode==='destinations'?'bands:0':'mission');return}if(mode==='destinations'){paragraph('Choose a place. Travel and positioning happen automatically.');for(const o of activeObjects())button(o.icon+' '+o.name,()=>{close();state.paused=false;$('#pause').innerHTML='Ⅱ <span>Pause</span>';select(o)});return}open('PIP helper');paragraph('Built-in offline guidance. This helper is not a live AI chat service.');const suggestion=helperSuggestion(activeObjects(),state.visited,state.last);if(suggestion)button('✨ Try '+suggestion.name,()=>{close();select(suggestion)});button('📍 Choose a destination',()=>{open('Choose a destination');adaptiveHelper('destinations')});button('↩ Previous activity',()=>{close();select(objects.find(o=>o.id===state.last)||objects.find(o=>o.id==='grounds-home'))});button('💬 My words',()=>adaptive.aac());}
