function firstVisitCrew(){open('Choose a J.A.C.C.');panel.classList.add('crew-panel');paragraph(firstVisitScript.crew);const grid=document.createElement('div');grid.className='crew-grid';content.append(grid);for(const r of roster){const b=button('',()=>{state.jaccBuilder.activeId=null;state.suit.overlay=null;characters.select(r[0]);updateCrew();persist();enterFirstVisitHQ();},grid);b.className='crew-card';b.setAttribute('aria-label',r[0]+', '+r[1]+', '+r[2]);const portrait=document.createElement('span');portrait.className='crew-portrait';portrait.style.setProperty('--suit',suitColors[r[1]]);portrait.setAttribute('aria-hidden','true');const name=document.createElement('strong');name.textContent=r[0];const detail=document.createElement('small');detail.textContent=r[1]+' • '+r[2];b.append(portrait,name,detail);}button('▶ Keep my astronaut — enter GSEINHQ',enterFirstVisitHQ);button('🔊 Listen',()=>readJournal(firstVisitScript.crew));speak(firstVisitScript.crew);}
