 const info=document.createElement('div');info.className='farm-info';const art=document.createElement('div');art.className='farm-art';art.innerHTML=magnetArt(v.art);art.setAttribute('role','img');art.setAttribute('aria-label',v.result);const p=document.createElement('p');p.textContent=v.text;info.append(art,p);content.append(info);
