function chapterDug(){return learnedDigging(state.visited,state.excavation,state.openWorld);}
function showChapter(page='desk'){
 const v=chapterView(state.chapter,page,state.firstVisit.mode,chapterDug());open(v.title);if(page==='desk')button('🌍 Generated exploration missions',()=>showExpedition('home'));panel.classList.add('farm-panel');const info=document.createElement('div');info.className='farm-info';const art=document.createElement('div');art.className='farm-art';art.innerHTML=chapterArt(v.art);if(v.art==='retreat'&&!state.settings.reduced&&state.settings.effects)art.classList.add('chapter-reaction');art.setAttribute('role','img');art.setAttribute('aria-label',v.title+'. '+v.text);const p=document.createElement('p');p.textContent=v.text;info.append(art,p);content.append(info);const choices=document.createElement('div');choices.className='farm-choices';content.append(choices);
 for(const [label,action]of v.actions)button(label,()=>{
 const result=chapterAction(state.chapter,action,state.firstVisit.mode,chapterDug(),state.zone);state.chapter=result.chapter;persist();chime();
 if(result.travel==='elevator-intro'){showElevator();return;}if(result.travel){close();start();state.paused=false;state.construction.active=null;state.construction.orbit=false;$('#pause').innerHTML='Ⅱ <span>Pause</span>';if(result.travel==='dig'){changeZone('dig');select(objects.find(o=>o.id==='dig-quartz'));return;}if(chapterWorlds[result.travel]){changeZone(result.travel);if(state.firstVisit.mode==='guided'&&action!=='earth-visit')showChapterClue();return;}select(objects.find(o=>o.id===result.travel));return;}
 showChapter(result.route);
 },choices);button('🔊 Listen',()=>readJournal(v.text),choices);button('🏠 Home hub',()=>{close();changeZone('grounds')},choices);speak(v.text);
}
function showChapterClue(){const next=chapterNext(state.chapter);if(!next)return;open('PIP’s chapter clue');paragraph('You could try '+next.name+'. Or keep exploring.');button(next.icon+' '+next.name,()=>{close();select(objects.find(o=>o.id===next.id))});button('Keep exploring',close);}
const chapterImages=new Map();function drawChapterProps(cx,cy){for(const o of chapterSites.filter(o=>o.zone===state.zone&&['guard1','guard2','station','machine1','machine2','energy'].includes(o.page))){if(o.page.startsWith('guard')&&state.chapter[o.page])continue;if(['station','energy'].includes(o.page)&&!state.chapter[o.page])continue;const key=o.page.startsWith('guard')?'nymion':o.page==='station'?'station':o.page==='energy'?'solar':state.chapter[o.page]?'machine-off':'machine';if(!chapterImages.has(key)){const img=new Image();img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(chapterArt(key));chapterImages.set(key,img);}const img=chapterImages.get(key);if(img.complete&&img.naturalWidth)ctx.drawImage(img,o.x-cx-85,o.y-cy-110,170,105);}}

function showElevator(page='intro',message=''){
 const v=elevatorView(state.elevator,page);open(v.title);panel.classList.add('farm-panel');const info=document.createElement('div');info.className='farm-info';const art=document.createElement('div');art.className='farm-art';art.innerHTML=elevatorArt(v.art);art.setAttribute('role','img');art.setAttribute('aria-label',v.title);const p=document.createElement('p');p.textContent=v.text;info.append(art,p);content.append(info);const choices=document.createElement('div');choices.className='farm-choices';content.append(choices);
 for(const [label,action]of v.actions)button(label,()=>{const result=elevatorAction(state.elevator,action);state.elevator=result.elevator;if(state.elevator.resolved)state.chapter.elevatorCleared=true;persist();refreshElevatorObjective();
 if(result.travel==='crew'){crewMenu(()=>showElevator());return;}if(result.travel==='chapters'||result.travel==='moon'){showChapter();return;}if(result.travel==='elevator'){close();start();state.paused=false;state.construction.active=null;state.construction.orbit=false;$('#pause').innerHTML='Ⅱ <span>Pause</span>';changeZone('elevator');return;}showElevator(result.route,result.message);
 },choices);button('🔊 Listen',()=>readJournal(v.text),choices);button('🏠 Home hub',()=>{close();changeZone('grounds')},choices);if(message)paragraph(message);speak(message||v.text);
}
function refreshElevatorObjective(){let el=document.getElementById('elevator-objective');if(!el){el=document.createElement('div');el.id='elevator-objective';el.setAttribute('role','status');document.getElementById('stage').append(el);}el.hidden=state.zone!=='elevator';if(!el.hidden){const d=state.elevator.deck;el.textContent=(d===6?'Upper platform':(d+1)+'/6 • '+elevatorDecks[d].name)+' — '+elevatorObjective(state.elevator);}}
const elevatorImages=new Map();function drawElevatorCompanions(){if(state.elevator.deck===6){const key=state.elevator.resolved?'escape':'zuglu';if(!elevatorImages.has(key)){const img=new Image();img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(elevatorArt(key));elevatorImages.set(key,img);}const img=elevatorImages.get(key);if(img.complete&&img.naturalWidth)ctx.drawImage(img,590,170,260,160);}for(const [i,index]of elevatorCast.filter(index=>activeCustomJacc(state.jaccBuilder)||roster[index]!==characters.active).entries()){const x=Math.max(50,Math.min(920,state.x-105+i*30)),y=Math.max(165,Math.min(475,state.y+12));rect(x-10,y-22,20,25,suitColors[roster[index][1]]);rect(x-11,y-40,22,18,'#c4ced8');rect(x-7,y-35,14,8,'#28495e');}if(state.elevator.deck===6&&!state.elevator.resolved&&state.settings.effects&&!state.settings.reduced){ctx.strokeStyle='#35aaa6';ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(720,300,110,45,0,0,Math.PI*2);ctx.stroke();}}

const gardenImages=new Map();function drawGardenBeds(){for(const [i,p]of state.farm.garden.plots.entries()){const key=farmArtKey(state.farm,'bed:'+i);if(!gardenImages.has(key)){const img=new Image();img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(farmArt(key));gardenImages.set(key,img);}const img=gardenImages.get(key);if(img.complete&&img.naturalWidth)ctx.drawImage(img,gardenBeds[i].x-48,362,96,54);}}

function machineCtx(){return {moonReady:chapterCanVisit('chapterMoon',state.firstVisit.mode,state.chapter,chapterDug()),earthReady:chapterCanVisit('chapterEarth',state.firstVisit.mode,state.chapter,chapterDug())};}
function showMachines(route='home',message=''){
 const v=machineView(state.machines,route,machineCtx());open(v.title);panel.classList.add('farm-panel');const info=document.createElement('div');info.className='farm-info';const art=document.createElement('div');art.className='farm-art machine-art';art.innerHTML=v.library?.length?machineLibrarySvg(v.library):machineSvg(v.design,{demo:v.demo,reduced:state.settings.reduced});art.setAttribute('role','img');art.setAttribute('aria-label',v.title+'. '+v.text);const p=document.createElement('p');p.textContent=v.text;info.append(art,p);content.append(info);const choices=document.createElement('div');choices.className='farm-choices';content.append(choices);
 for(const a of v.actions)button(a.label,()=>{const result=machineCommand(state.machines,a,machineCtx());state.machines=result.machines;persist();chime();if(result.effect==='water-bed'){const bed=state.farm.garden.plots.findIndex(p=>p.seed&&p.stage<3&&!p.watered);if(bed>=0)state.farm=farmAction(state.farm,{type:'garden',command:'water',bed}).farm;persist();}if(result.effect==='farm-light'){state.farm.sun=true;persist();}if(result.travel){close();start();state.paused=false;state.construction.active=null;state.construction.orbit=false;$('#pause').innerHTML='Ⅱ <span>Pause</span>';if(changeZone(result.travel)===false)return;if(result.route===null)return;showMachines(result.route,result.message);return;}showMachines(result.route,result.message);},choices);
 button('🔊 Listen',()=>readJournal(v.text),choices);if(message)paragraph(message,'farm-message');machineUI={...v,phase:0};speak(message||v.title+'. '+v.text);
}
function updateMachineDemo(dt){if(!state.paused&&!panel.open&&!state.settings.reduced)machineWorldPhase+=dt;if(!machineUI?.demo||!panel.open||state.paused)return;if(!state.settings.reduced)machineUI.phase+=dt;const p=machineMotion(machineUI.design.type,machineUI.phase,state.settings.reduced),svg=content.querySelector('.machine-art svg');svg?.querySelector('[data-machine-body]')?.setAttribute('transform','translate('+p.x+' '+p.y+')');svg?.querySelector('[data-machine-cargo]')?.setAttribute('transform','translate(0 '+p.cargoY+')');svg?.querySelector('[data-machine-helper]')?.setAttribute('transform','translate('+p.helperX+' 0)');}
const machineImages=new Map();function drawMachinePlacements(){if(state.construction.active||state.construction.orbit)return;const camera=spaceCamera(state.zone,[state.x,state.y]);for(const p of state.machines.placements.filter(p=>p.site===state.zone)){const d=p.snapshot,key=JSON.stringify(d);if(!machineImages.has(key)){const img=new Image();img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(machineSvg(d,{background:false}));machineImages.set(key,img);if(machineImages.size>64)machineImages.delete(machineImages.keys().next().value);}const img=machineImages.get(key),[x,y]=machineSites[p.site].pads[p.pad],motion=machineMotion(d.type,machineWorldPhase,state.settings.reduced);if(p.site==='machineyard'&&d.type==='submarine'){rect(x-100,y-105,200,110,'#79bacb');}if(img.complete&&img.naturalWidth)ctx.drawImage(img,x-camera[0]-90+motion.x*.5,y-camera[1]-100+motion.y*.5,180,100);if(d.type==='bridge'){rect(x-camera[0]-90+motion.helperX*.5,y-camera[1]-84,9,14,'#35bcb8');}if(d.type==='crane')rect(x-camera[0]+43,y-camera[1]-45+motion.cargoY*.5,16,13,'#bc9b6c');if(['solar','habitat','tower'].includes(d.type)){ctx.fillStyle='#e8ca6a';ctx.beginPath();ctx.arc(x-camera[0]+75,y-camera[1]-80,7,0,Math.PI*2);ctx.fill();}}}

function techCtx(){return {zone:state.zone,robots:state.machines.models.filter(m=>m.type==='helperbot').map(m=>({...m,name:machineName(m),toolName:machineParts[m.parts.module].name}))};}
function showTech(route='home',message=''){const v=techView(state.tech,route,techCtx());open(v.title);panel.classList.add('farm-panel');const info=document.createElement('div');info.className='farm-info';const art=document.createElement('div');art.className='farm-art';art.innerHTML=techArt(techArtKey(state.tech,v.art));art.setAttribute('role','img');art.setAttribute('aria-label',v.title+'. '+v.text);const p=document.createElement('p');p.textContent=v.text;info.append(art,p);content.append(info);const choices=document.createElement('div');choices.className='farm-choices';content.append(choices);for(const a of v.actions)button(a.label,()=>{const result=techAction(state.tech,a,techCtx());state.tech=result.tech;let note=result.message;if(result.effect==='farm'){const bed=state.farm.garden.plots.findIndex(p=>p.seed&&p.stage<3&&!p.watered);if(bed>=0){state.farm=farmAction(state.farm,{type:'garden',command:'water',bed}).farm;note='Your helper watered a farm bed. Return to the farm to see its next growth stage.';}else note='No farm bed needs water. The helper watered a practice pot.';}if(result.effect==='construction'){const active=state.construction.active;openBuild(state.construction,'free');buildAction(state.construction,'robot');state.construction.active=active;note='Your helper added a prefab plan to the free-build board in Engineering.';}persist();chime();if(result.blueprint){const built=machineCommand(state.machines,{type:'blueprint',value:result.blueprint},machineCtx());state.machines=built.machines;persist();showMachines(built.route);return}if(result.pip){pipWorkshop();return}if(result.home){close();select(objects.find(o=>o.id==='grounds-home'));return}showTech(result.route,note);},choices);button('🔊 Listen',()=>readJournal(v.text+(message?' '+message:'')));if(message){paragraph(message);announce(message);} }

function activeAstronautName(){return activeCustomJacc(state.jaccBuilder)?.name||characters.active[0];}
