let jaccAfterSelect=null;
function showJaccBuilder(route='home',afterSelect){if(arguments.length>1)jaccAfterSelect=typeof afterSelect==='function'?afterSelect:null;const v=jaccBuilderView(state.jaccBuilder,route);open(v.title);panel.classList.add('farm-panel');const info=document.createElement('div');info.className='farm-info';const art=document.createElement('div');art.className='farm-art jacc-preview';art.innerHTML=jaccSvg(v.design);art.setAttribute('role','img');art.setAttribute('aria-label',v.design.name+', helmet '+v.design.colors.helmet+', armor '+v.design.colors.armor+', boots '+v.design.colors.boots);const p=document.createElement('p');p.textContent=v.text;info.append(art,p);content.append(info);const choices=document.createElement('div');choices.className='farm-choices';content.append(choices);for(const a of v.actions)button(a.label,()=>{const result=jaccBuilderAction(state.jaccBuilder,a);state.jaccBuilder=result.builder;if(result.play){state.suit.overlay=null;persist();updateCrew();close();announce(activeAstronautName()+' is ready to explore.');const cb=jaccAfterSelect;jaccAfterSelect=null;if(cb)cb();return}persist();showJaccBuilder(result.route);if(result.message){paragraph(result.message);announce(result.message);}},choices);if(v.actions.length<6)button('🔊 Listen',()=>readJournal(v.title+'. '+v.text+' '+v.actions.map(a=>a.label).join('. ')));}
function customSuitMenu(){const d=activeCustomJacc(state.jaccBuilder);open('My astronaut tools');paragraph(d.name+' • Mix your STEM core and arm tools. Every activity remains available.');for(const [slot,label]of [['core','STEM core'],['left','Left arm'],['right','Right arm']]){const tool=customJaccTool(d,slot);button(label+': '+tool.name,()=>{if(tool.power){showSuitPower(tool.power);return}if(tool.target){close();select(objects.find(o=>o.id===tool.target));return}announce('A plain glove. Choose a tool in your astronaut workshop.');});}button('◎ Clear suit overlay',()=>{state.suit.overlay=null;persist();close();});button('🎨 Edit my J.A.C.C.',()=>{state.jaccBuilder=jaccBuilderAction(state.jaccBuilder,{type:'edit',id:d.id}).builder;showJaccBuilder('home',null);});button('🧑‍🚀 Choose the main crew',crewMenu);}
let customAvatarKey='',customAvatarImage=null;
function drawCustomAstronaut(x,y,bob=0){const d=activeCustomJacc(state.jaccBuilder),key=JSON.stringify(d);if(key!==customAvatarKey){customAvatarKey=key;customAvatarImage=new Image();customAvatarImage.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(jaccSvg(d));}if(state.zone==='aquatic'&&state.aquatic.vehicle==='sub'){ctx.fillStyle='#efd17c';ctx.beginPath();ctx.ellipse(x,y-8,61,35,0,0,Math.PI*2);ctx.fill();rect(x-76,y-20,20,24,'#e0bb64');ctx.fillStyle='#9bcbd7';ctx.beginPath();ctx.ellipse(x,y-10,33,29,0,0,Math.PI*2);ctx.fill();if(customAvatarImage?.complete&&customAvatarImage.naturalWidth)ctx.drawImage(customAvatarImage,x-15,y-33,30,40);return;}if(customAvatarImage?.complete&&customAvatarImage.naturalWidth){ctx.save();ctx.translate(x,y-30+bob);if(state.zone==='aquatic')ctx.rotate(Math.PI/2);ctx.drawImage(customAvatarImage,-30,-40,60,80);ctx.restore();}}

function rocketCtx(){return {rockets:state.machines.models.filter(m=>m.type==='rocket')};}
function showRocketLab(route='home',message=''){const v=rocketView(state.rocketLab,route,rocketCtx());open(v.title);panel.classList.add('farm-panel');const info=document.createElement('div');info.className='farm-info';const art=document.createElement('div');art.className='farm-art';art.innerHTML=rocketPanelSvg(v);art.setAttribute('role','img');art.setAttribute('aria-label',v.title+'. '+v.text);const p=document.createElement('p');p.textContent=v.text;info.append(art,p);content.append(info);const choices=document.createElement('div');choices.className='farm-choices';content.append(choices);for(const a of v.actions)button(a.label,()=>{const r=rocketAction(state.rocketLab,a,rocketCtx());state.rocketLab=r.lab;persist();chime();if(r.build){const built=machineCommand(state.machines,{type:'blueprint',value:'rocket'},machineCtx());state.machines=built.machines;persist();showMachines(built.route);return}if(r.home){close();select(objects.find(o=>o.id==='grounds-home'));return}showRocketLab(r.route,r.message);},choices);button('🔊 Listen',()=>readJournal(v.text+(message?' '+message:'')));if(message){paragraph(message);announce(message);}}
const rocketWorldImages=new Map();function drawRocketWorld(){if(state.zone!=='rocketlab'||state.construction.active||state.construction.orbit)return;const lab=state.rocketLab,p=rocketWorldPose(lab.phase),d=lab.snapshot;if(!d||!p.visible)return;const key=JSON.stringify(d);if(!rocketWorldImages.has(key)){const img=new Image();img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(machineSvg(d,{background:false}));rocketWorldImages.set(key,img);if(rocketWorldImages.size>12)rocketWorldImages.delete(rocketWorldImages.keys().next().value);}const img=rocketWorldImages.get(key);if(img.complete&&img.naturalWidth)ctx.drawImage(img,p.x,p.y,360*p.scale,200*p.scale);if(p.flame&&state.settings.effects){ctx.fillStyle='#35d3c9';ctx.beginPath();ctx.moveTo(p.x+167*p.scale,p.y+183*p.scale);ctx.lineTo(p.x+177*p.scale,p.y+221*p.scale);ctx.lineTo(p.x+187*p.scale,p.y+183*p.scale);ctx.closePath();ctx.fill();}}

const expRoot=document.createElement('div');expRoot.id='expedition-ui';expRoot.hidden=true;$('#stage').append(expRoot);const expTargets=document.createElement('div');expTargets.className='expedition-targets';expRoot.append(expTargets);const expTargetButtons=Array.from({length:8},(_,i)=>{const b=document.createElement('button');b.className='expedition-target';b.dataset.slot=i;b.onclick=()=>{const item=expItems[i];if(item)tapExpedition(item,{kind:'item',item});};expTargets.append(b);return b;});let expItems=[];
const expFooter=document.createElement('div');expFooter.className='expedition-footer';expRoot.append(expFooter);const expControlButtons={};for(const [id,label,action]of [['left','← Trail',{type:'step',dx:-1}],['right','Trail →',{type:'step',dx:1}],['up','↑ Up',{type:'step',dy:-1}],['down','↓ Down',{type:'step',dy:1}],['flight','Wings',{type:'flight'}],['bands','Layers / map',{type:'page',route:'bands:0'}],['goal','PIP goal',{type:'page',route:'mission'}],['tools','Tools / trails',{type:'page',route:'options'}],['exit','Home',{type:'exit'}]]){const b=document.createElement('button');b.textContent=label;b.dataset.expControl=id;b.className=['left','right','up','down'].includes(id)?'expedition-edge expedition-'+id:'';b.onclick=()=>runExpeditionAction(action);(['left','right','up','down'].includes(id)?expRoot:expFooter).append(b);expControlButtons[id]=b;}
function expeditionCtx(){return {plants:farmPlants.filter(p=>state.farm.seeds.includes(p.id))};}
function applyExpeditionEffect(effect){if(!effect)return;if(effect.seed)state.farm=farmAction(state.farm,{type:'collect',id:effect.seed,origin:state.expeditions.active==='forest'?'forest':'tray'}).farm;if(effect.material){state.discoveries.add(effect.material);state.visited.add('dig');}if(effect.life&&aquaticLife.some(o=>o.id===effect.life)&&!state.aquatic.observed.includes(effect.life))state.aquatic.observed.push(effect.life);if(effect.harvest){for(const key of ['harvested'])if(!state.farm.garden[key].includes(effect.harvest))state.farm.garden[key].push(effect.harvest);}}
function enterExpedition(mode,focus){close();state.construction.active=null;state.construction.orbit=false;state.path=[];state.pending=null;state.action=null;expeditionRevisit(state.expeditions,mode,focus);start();state.paused=false;$('#pause').innerHTML='Ⅱ <span>Pause</span>';renderTargets();persist();announce(expeditionModes[mode].name+'. Tap a destination or ask PIP for one goal.');}
function exitExpedition(){const parent=state.zone;state.expeditions.active=null;expRoot.hidden=true;if(parent==='farm')state.farm=returnToFarm(state.farm);changeZone(parent);persist();}
function showExpedition(route='home'){const v=expeditionView(state.expeditions,route,expeditionCtx());open(v.title);panel.classList.add('farm-panel');paragraph(v.text,'journal-intro');const choices=document.createElement('div');choices.className='farm-choices';content.append(choices);for(const a of v.actions)button(a.label,()=>runExpeditionAction(a),choices);if(v.actions.length<6)button('🔊 Listen',()=>readJournal(v.title+'. '+v.text+' '+v.actions.map(a=>a.label).join('. ')));}
function runExpeditionAction(a){if(state.paused&&!['page','exit','crew'].includes(a.type)){announce('Tap Resume when you want to travel.');return;}if(a.type==='crew'){close();crewMenu();return}if(a.type==='enter'){enterExpedition(a.mode);return}const r=expeditionAction(state.expeditions,a,expeditionCtx());applyExpeditionEffect(r.effect);if(r.exit){close();exitExpedition();return}persist();if(r.route===null)close();else showExpedition(r.route);if(r.message)announce(r.message);}
function tapExpedition(point,pending=null){if(state.paused||panel.open)return;const s=state.expeditions,w=s.worlds[s.active];if(w.tool!=='explore'){announce(expeditionPlace(s,point));persist();return;}if(!pending&&s.active==='farm'){const x=Math.floor(point.x/40),y=Math.floor(point.y/40);if(expeditionCell(w,'farm',x,y).plantable)pending={kind:'plot',key:x+','+y};}const ok=expeditionRequest(s,point,pending);announce(ok?'Traveling automatically. Tap again to choose another destination.':'Try a nearby ledge, tree trunk, open water or backpack flight.');}
let lastExpSave=0;function tickExpedition(dt){const r=expeditionTick(state.expeditions,dt);if(r.arrived?.kind==='item'){const found=expeditionInteract(state.expeditions,r.arrived.item);applyExpeditionEffect(found.effect);announce(found.message);chime();}if(r.arrived?.kind==='plot'){state.expeditions.worlds.farm.selectedPlot=r.arrived.key;showExpedition('plot');}if(r.changed&&(r.arrived||performance.now()-lastExpSave>250)){persist();lastExpSave=performance.now();}}
